GLOSSARY = {
    "prompt": ("Prompt", "The instruction you give Claude. It can include the task, background, source material and how you want the answer laid out."),
    "hallucination": ("Hallucination", "When an AI model states something that sounds right but has no basis in the material it was given or in fact. Fluent wording is not evidence."),
    "objective": ("Objective", "The piece of work you want done, stated as a deliverable. 'Draft a status update' is an objective. 'Patching' is only a topic."),
    "context": ("Context", "Background that gives the task meaning: the project, the environment, what happened before. Also used for everything Claude can see in the current conversation."),
    "authoritative": ("Authoritative input", "The material you tell Claude to treat as the source of truth for this task. It is authoritative because your prompt says so."),
    "audience": ("Audience", "The people who will read the result. Their knowledge and needs decide the vocabulary, level of detail and tone."),
    "constraint": ("Constraint", "A boundary on the answer: what to leave out, what must not be claimed, which terms to use, how to treat missing information."),
    "format": ("Output format", "The shape of the answer: headings, a table, bullet points, a length limit. It says how to lay facts out. It does not supply the facts."),
    "evidence-boundary": ("Evidence boundary", "The line between what the supplied material supports and everything else. A good prompt tells Claude to stay inside it and say so when it reaches the edge."),
    "observable": ("Observable requirement", "A requirement a reviewer can check by looking: 'three headed paragraphs, under 150 words'. The opposite is a vague quality word like 'polished'."),
    "root-cause": ("Root cause", "The underlying reason a fault happened. It should only be stated once evidence supports it. Until then it is a hypothesis."),
    "hypothesis": ("Hypothesis", "A possible explanation that has not been proven yet. Keep it labelled as one until a check confirms or rules it out."),
    "diagnostic-loop": ("Diagnostic loop", "A troubleshooting routine: describe the fault, have Claude write one script that collects evidence, feed the output back, and only then reason about the cause. Repeat until the evidence proves it."),
    "decomposition": ("Decomposition", "Splitting a large job into smaller stages, each with its own input and its own checkable result."),
    "one-shot": ("One-shot prompt", "A single prompt that asks for the whole finished result in one go."),
    "intermediate": ("Intermediate deliverable", "A result produced part-way through a job, such as an extracted list of facts, that can be checked before later stages rely on it."),
    "inventory": ("Input inventory", "A list of everything the job should cover and every source it should draw on, written before any analysis starts."),
    "completeness-check": ("Completeness check", "Comparing what was actually extracted against the inventory, to catch anything that was skipped."),
    "human-gate": ("Human gate", "A stopping point where a person checks the work so far and decides whether Claude should carry on. Also called a checkpoint."),
    "dependency": ("Dependency", "Something that has to be finished and correct before the next thing can be trusted. Facts before analysis, analysis before recommendations."),
    "iteration": ("Iteration", "Improving a result through repeated rounds: get a draft, inspect it, name the main defect, revise the instruction, compare."),
    "defect": ("Defect", "The specific thing wrong with a draft. Naming its type (missing content, wrong tone, unsupported claim and so on) tells you which fix to use."),
    "knowledge-gap": ("Knowledge gap", "The answer is not in the material Claude was given. No amount of rewording the prompt fixes this. Someone has to supply the fact."),
    "rubric": ("Rubric", "A short list of criteria a draft must meet, written so each one can be ticked or crossed."),
    "follow-up": ("Follow-up prompt", "A new instruction in the same conversation that builds on what is already there, instead of starting again."),
    "context-drift": ("Context drift", "When a long conversation fills up with old drafts and replaced instructions, and Claude starts mixing outdated material back into new answers."),
    "analysis": ("Analysis", "Using evidence you already have to reach a decision: comparing options against stated criteria."),
    "research": ("Research", "Finding evidence and showing where each piece came from, including what could not be found."),
    "drafting": ("Drafting", "Turning agreed facts and a chosen direction into a piece of writing for a particular reader."),
    "brainstorming": ("Brainstorming", "Producing a wide spread of possible approaches before anyone judges them."),
    "chaining": ("Prompt chaining", "Running several prompts in order, where each one uses the checked result of the one before."),
    "recency": ("Recency", "How recent a source has to be to count. A research prompt should say so, for example 'published in the last 12 months'."),
    "citation": ("Citation", "A pointer from a statement to the source that supports it, so a reviewer can trace it."),
    "assumption": ("Assumption", "Something treated as true for the sake of the work without being proven. Good analysis lists assumptions separately from findings."),
    "change-board": ("Change board", "The group that approves changes to live systems before they are made. Often called CAB, the change advisory board."),
    "ccao-f": ("CCAO-F", "Claude Certified Associate, Foundations. Anthropic's entry-level certification exam on using Claude well for everyday work."),
    "unsupported-claim": ("Unsupported claim", "A statement presented as fact that the authoritative source does not back, at the strength or level of detail used."),
    "inference": ("Inference", "A reasoned interpretation drawn from the evidence. It is acceptable when it is clearly labelled as an inference and not passed off as a source fact."),
    "unresolved": ("Unresolved question", "Something the source does not answer. Recording it as open is more accurate than filling it with an assumption."),
    "internal-consistency": ("Internal consistency", "Whether a response agrees with itself and with its own source from start to finish: numbers, units, labels, definitions and conclusions."),
    "external-error": ("External factual error", "A statement that conflicts with a reliable source outside the response, such as a wrong published date or price."),
    "ambiguous-reference": ("Ambiguous reference", "A word such as 'it' or 'this option', or an undefined label such as 'better coverage', where the reader cannot tell what is meant."),
    "terminology-shift": ("Terminology shift", "A key term that changes meaning part-way through a response while the wording stays similar."),
    "bias": ("Bias", "A systematic distortion that produces unfair, incomplete or poorly supported outcomes. It can sit behind perfectly neutral wording."),
    "proxy": ("Proxy variable", "An indirect attribute used in place of a real job-relevant criterion, such as employer prestige standing in for ability."),
    "framing-bias": ("Framing bias", "When the way a question is asked steers the answer toward a narrow idea of what counts, such as asking for 'executive polish' in place of evidence of the role's duties."),
    "stereotyping": ("Stereotyping", "Assuming abilities, values or behaviour based on a person's group or background."),
    "factual-imbalance": ("Factual imbalance", "A measurable gap in the record itself, such as feedback that came from managers and from none of the people affected."),
    "unrepresentative": ("Unrepresentative sample", "A set of sources that cannot reasonably support conclusions about the wider group affected."),
    "consequential": ("Consequential decision", "A decision that can significantly affect a person's job, pay, opportunity or advancement, or carries real safety, legal or financial weight."),
    "primary-source": ("Primary source", "The original authority for a fact, such as the manufacturer's specification or the policy owner's document."),
    "qualifier": ("Qualifier", "A condition attached to a claim, such as 'up to', 'under test conditions' or 'for eligible customers'. Dropping it changes the meaning."),
    "effective-date": ("Effective date", "When a rule actually applies. It can differ from the date the document was published."),
    "evidence-log": ("Evidence log", "A compact record of each claim, its source, the source date, the supporting passage, your interpretation and a status."),
    "validation": ("Validation", "Testing whether each claim is supported by an authoritative source that is good enough for the intended use. Editing only changes how it reads."),
    "structured-data": ("Structured data", "Output laid out in fixed fields, such as a table or record, so it can be filtered, compared, reused or passed to another system."),
    "artifact": ("Artifact", "A standalone piece of work Claude builds beside the conversation, such as a document, tracker or small tool, that you can come back to, edit and share."),
    "chat": ("Chat", "An ordinary conversation with Claude. Suited to direct work where everything needed can be supplied in that conversation."),
    "project": ("Project", "A self-contained workspace in Claude with its own chats, instructions and knowledge files, for related or recurring work."),
    "project-instructions": ("Project instructions", "Standing rules for how Claude should work in every chat inside one Project."),
    "project-knowledge": ("Project knowledge", "Reference files added to a Project so every chat in it can draw on the same material."),
    "research-feature": ("Research", "A Claude capability that searches across many sources over several steps, pulls the findings together and cites where each came from."),
    "model": ("Model", "The underlying AI that does the work. Different models trade capability against speed and cost."),
    "haiku": ("Haiku", "Claude's fastest, most economical model family. Suited to clear, high-volume work."),
    "sonnet": ("Sonnet", "Claude's balanced model family: capable, reasonably fast and cost-efficient for most professional work."),
    "opus": ("Opus", "Claude's most capable of the three families covered by the exam. Suited to difficult reasoning where a better answer is worth extra cost and time."),
    "latency": ("Latency", "How long you wait for a response."),
    "service-requirement": ("Service requirement", "What a piece of work must achieve to be acceptable: minimum quality, turnaround time, volume, and what happens if an error gets through."),
    "acceptance-criteria": ("Acceptance criteria", "Measurable conditions an output must meet, set before any models are compared."),
    "total-cost": ("Total cost", "Model usage cost plus reviewer time, rework, delay and the impact of errors that get past review."),
    "pilot": ("Pilot", "A small, controlled trial on realistic work, used to gather evidence before a wider rollout."),
    "blind-comparison": ("Blind comparison", "Scoring outputs without knowing which model or method produced them, so expectations cannot sway the result."),
    "escalation-threshold": ("Escalation threshold", "A clear, observable condition that sends a case to a stronger model or a person. 'Any privileged access request' is a threshold. 'If it seems hard' is not."),
    "handoff-summary": ("Handoff summary", "A short note carrying only what a new conversation needs: current task, authoritative facts, what not to use, and open questions."),
    "memory": ("Memory", "A Claude feature that remembers things about you across conversations to personalise responses. It is not an authoritative record of facts or approvals."),
    "data-minimisation": ("Data minimisation", "Keeping only the information that has a clear purpose, the right authorisation and a suitable place to live."),
    "use-case": ("Use case", "A defined piece of work that produces a useful result for a defined user."),
    "requirement": ("Requirement", "A condition, capability or constraint the work needs."),
    "ambiguity": ("Ambiguity", "Information that is missing, unclear or open to more than one reading."),
    "three-tests": ("Feasible, valuable, permissible", "The three tests a use case must pass. It can be done with the inputs available, it improves something that matters, and it is allowed under data, policy and authorisation rules."),
    "research-design": ("Research design", "The plan made before researching: the questions, the boundaries, which sources can support each claim, and how options will be compared."),
    "interested-party": ("Interested-party claim", "A claim from someone who benefits from the outcome, such as a vendor's quote. Useful for follow-up, but not proof."),
    "evidence-ledger": ("Evidence ledger", "A table that keeps each claim with its evidence, source, uncertainty and what it means for the plan."),
    "scenario-planning": ("Scenario planning", "Working through what happens to the plan if a key assumption changes."),
    "decision-gate": ("Decision gate", "A point where an authorised person approves, defers or rejects before money or commitments follow."),
    "process": ("Process", "The repeatable sequence of people, information, decisions and tools that produces an outcome."),
    "current-state": ("Current-state map", "A record of how the process really runs today: trigger, steps, handoffs, systems, waiting, exceptions and outcome."),
    "friction": ("Friction", "Effort, delay, confusion or failure that makes a process harder to complete."),
    "rework": ("Rework", "Work done again because the first version was incomplete, inconsistent or unsuitable for its next use."),
    "baseline": ("Baseline", "A measurement taken before a change, so the result afterwards can be compared like with like."),
    "augmentation": ("Augmentation", "Using a tool to help a person do judgement-based work. The person still does the work and owns the result."),
    "automation": ("Automation", "Having a system carry out a repeatable action with little human involvement."),
    "solution-boundary": ("Solution boundary", "A statement of what a workflow owns and what stays outside it: the input, the output, the reviewer and the decisions it must not make."),
    "schema": ("Schema", "The required structure for each result, such as a fixed set of fields. It makes output easy to check, route and compare."),
    "fallback": ("Fallback", "What happens when the normal route fails, such as a manual template the person uses instead."),
    "prompt-injection": ("Prompt injection", "Text inside the material being processed that tries to give Claude new instructions, such as 'ignore the categories'. It should be treated as data."),
    "controlled-revision": ("Controlled revision", "Changing one component, keeping everything else the same, and rerunning the same test so you can see what the change did."),
    "redesign": ("Redesign", "Changing the process itself because Claude makes a different approach practical, such as self-service for routine questions."),
    "residual-risk": ("Residual risk", "What can still go wrong after the controls are in place."),
    "value-case": ("Value case", "The argument for a change: baseline, expected improvement, implementation cost, residual risk and when results will be reviewed."),
}
